const monitorSection=document.createElement('section');monitorSection.className='monitor-workspace';monitorSection.innerHTML='<div class="monitor-heading"><div><span class="eyebrow">PERSISTENT OBSERVATION ENGINE</span><h2>Always watching for a change</h2><p>Road conditions across connected regions · every observation is open for review</p></div><button class="button" id="monitor-toggle" disabled>Connecting</button></div><div class="monitor-strip"><span id="monitor-state">Connecting monitor</span><span id="monitor-coverage">Loading coverage</span><span id="monitor-spend">Checking compute</span></div><div class="monitor-reports" id="monitor-reports"><p>The first observation will appear here when the background check finishes</p></div><p class="monitor-note">Runs while this local server and computer are on, even when the browser is closed · Checks source images every 2–10 minutes · Reviews visible conditions, not identities or guilt · $1 estimated daily spend guard, resetting at midnight UTC</p>';
document.querySelector('#live-workspace').append(monitorSection);let currentMonitor=null,monitorFetching=false;
function inspectObservation(report){openInfo('OBSERVATION / '+report.id.slice(0,8).toUpperCase(),'<h2>'+escapeHtml(report.evidence.cameraName)+'</h2><div class="evidence-header"><span class="pill">AI OBSERVATION · HUMAN REVIEW</span><span class="pill">'+escapeHtml(report.model)+'</span></div><a href="'+escapeHtml(report.evidence.image)+'" target="_blank" rel="noopener"><img class="record-image" src="'+escapeHtml(report.evidence.image)+'" alt="Original source frame used for this observation"></a><div class="record-timestamp">Retrieved '+escapeHtml(new Date(report.evidence.fetchedAt).toLocaleString())+' · Capture time is embedded in the source</div><pre class="record-summary">'+escapeHtml(report.text)+'</pre><div class="dialog-note">One image does not establish motion, persistence, intent, or the cause of an event</div><div class="record-hash">SHA-256 '+escapeHtml(report.hash)+'</div><a href="'+escapeHtml(report.evidence.source)+'" target="_blank" rel="noopener" class="button">Open official camera source ↗</a>');}
async function refreshMonitor(){if(monitorFetching||document.hidden)return;monitorFetching=true;try{const response=await fetch('/api/monitor');if(!response.ok)throw new Error();const data=await response.json();currentMonitor=data;const state=document.querySelector('#monitor-state');state.textContent=!data.configured?'AI offline':data.lastError?data.lastError:data.spent>=data.budget?'Daily spend guard reached':data.enabled?(data.running?'● Analyzing a camera':'● Background monitoring active'):'Monitoring paused';state.title=data.lastError||'Checks continue without an open browser';document.querySelector('#monitor-coverage').textContent=data.cameras+' cameras · 4 countries';document.querySelector('#monitor-spend').textContent=liveMoney(data.spent)+' / $1 today';const toggle=document.querySelector('#monitor-toggle');toggle.disabled=!data.configured;toggle.textContent=data.enabled?'Pause monitoring':'Resume monitoring';document.querySelector('#monitor-reports').innerHTML=data.history.length?data.history.slice(0,6).map(r=>'<button class="monitor-report" data-record="'+escapeHtml(r.id)+'"><img src="'+escapeHtml(r.evidence.image)+'" alt="'+escapeHtml(r.evidence.cameraName)+' source frame"><span><small>'+escapeHtml(r.evidence.provider)+' · '+liveTime(r.completedAt)+'</small><b>'+escapeHtml(r.evidence.cameraName)+'</b><span>'+escapeHtml(r.text.replace(/^OBSERVATION:?\s*/i,'').slice(0,130))+'</span><em>Inspect observation ↗</em></span></button>').join(''):'<p>'+(data.lastError?escapeHtml(data.lastError):'The first observation will appear here when the background check finishes')+'</p>';document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>inspectObservation(data.history.find(r=>r.id===b.dataset.record)));if(liveState.status)liveState.status.spent=data.spent;}catch{document.querySelector('#monitor-state').textContent='Local monitor unavailable';}finally{monitorFetching=false;}}
document.querySelector('#monitor-toggle').onclick=async()=>{if(!currentMonitor||!liveState.status)return;const b=document.querySelector('#monitor-toggle');b.disabled=true;try{const response=await fetch('/api/monitor',{method:'POST',headers:{'Content-Type':'application/json','X-Parallax-Token':liveState.status.csrf},body:JSON.stringify({enabled:!currentMonitor.enabled})});if(!response.ok)throw new Error();await refreshMonitor();}catch{b.textContent='Could not change monitor';b.disabled=false;}};
refreshMonitor();setInterval(refreshMonitor,10000);
// Display copy follows the site's punctuation style; preserve exact model observations and evidence.
function stripDisplayPeriods(root){if(root.nodeType===Node.TEXT_NODE){if(!root.parentElement?.closest('script,style,textarea,pre,.analysis-output,.record-summary,.record-hash')){const next=root.nodeValue.replace(/\.(?=\s|$)/g,'');if(next!==root.nodeValue)root.nodeValue=next;}return;}if(root.nodeType!==Node.ELEMENT_NODE)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())stripDisplayPeriods(node);}
stripDisplayPeriods(document.body);new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')stripDisplayPeriods(record.target);else record.addedNodes.forEach(stripDisplayPeriods);}}).observe(document.body,{childList:true,subtree:true,characterData:true});
